package com.pp.shaderlod.optimization.blisspixel;
import com.pp.shaderlod.LodPreset;import com.pp.shaderlod.optimization.*;import net.irisshaders.iris.Iris;import net.irisshaders.iris.platform.IrisPlatformHelpers;import net.irisshaders.iris.targets.RenderTargets;import net.irisshaders.iris.uniforms.SystemTimeUniforms;import com.pp.shaderlod.optimization.blisspixel.mixin.*;import java.nio.file.*;import java.util.*;import org.lwjgl.opengl.*;
/** Actual normal graph/frame producer, preparation return, full reconstruction and coherent recovery. */
public final class BlissPixelRuntime {
 private static boolean pending,recovering,retryBlocked;private static long blockedGeneration;
 private static final BlissPixelFrame FRAME=new BlissPixelFrame();private static boolean installed,active,sourceQualified,profileQualified,layoutQualified,nearQualified,clear,prepared,taaReturned;private static Object pipeline,composite,pack;private static RenderTargets targets;private static BlissPixelFrame.Key key;private static long sourceEpoch;private static float rain=-1;private static BlissPixelPassView prep,taa;private static int startedProgram,first,second;private static String failure="not rendered";
 private BlissPixelRuntime(){}
 public static void install(){if(installed)return;installed=true;CompileOptionControl.configureAdmission(BlissPixelContract.ID,OptimizationId.PIXEL_SCALE,BlissPixelRuntime::setupAdmitted);}
 public static String failure(){return failure;}
 private static Path selected(){String name=Iris.getIrisConfig().getShaderPackName().orElse(null);if(name==null)return null;var d=Iris.getShaderpacksDirectory().toAbsolutePath().normalize();var p=d.resolve(name).normalize();return p.startsWith(d)&&!p.equals(d)?p:null;}
 private static boolean source(){
  return com.pp.shaderlod.optimization.sourcecache.IrisSourceLifecycle.proof(java.util.Arrays.asList(BlissPixelRuntime.class,"source"),()->{return !Iris.isFallback()&&BlissPixelSourceProof.verify(selected(),()->BlissPixelRuntime.class.getResourceAsStream("/assets/shaderlod/adapters/patches/adapters/bliss-shader.json"));
  });
 }
 private static Map<String,String> options(boolean verified){var p=Iris.getCurrentPack().orElse(null);if(p==null)return Map.of();var o=p.getShaderPackOptions();return BlissPixelOptionGuard.snapshot(o.getOptionSet(),o.getOptionValues(),verified);}
 private static boolean environment(){var p=IrisPlatformHelpers.getInstance();return BlissPixelApiPins.exact()&&!Iris.isFallback()&&!p.isModLoaded("distanthorizons")&&!p.isModLoaded("voxy");}
 private static boolean requested(){var c=OptimizationRuntimeContext.core();return c!=null&&c.settings().enabled()&&c.preset()!=LodPreset.QUALITY&&c.optimizations().enabled(OptimizationId.PIXEL_SCALE)&&OptimizationConfig.requested(OptimizationId.PIXEL_SCALE);}
 public static boolean setupAdmitted(){install();var p=Iris.getCurrentPack().orElse(null);if(p==null||!environment()||(retryBlocked&&blockedGeneration==OptimizationConfig.generation()))return false;var e=BlissPixelEnvironment.actual();if(!e.overworld()||!e.clear())return false;retryBlocked=false;var o=p.getShaderPackOptions();if(BlissPixelOptionGuard.declaredGraph(o.getOptionSet(),o.getOptionValues()).isEmpty()||!source())return false;return BlissPixelContract.options(options(true));}
 public static void invalidate(){sourceEpoch++;FRAME.invalidate();active=sourceQualified=profileQualified=layoutQualified=nearQualified=clear=prepared=taaReturned=false;pipeline=composite=pack=null;targets=null;prep=taa=null;rain=-1;}
 public static void begin(Object p,RenderTargets t,Object renderer){install();active=sourceQualified=profileQualified=layoutQualified=nearQualified=clear=prepared=taaReturned=false;pipeline=p;targets=t;composite=renderer;pack=Iris.getCurrentPack().orElse(null);prep=taa=null;rain=-1;
  if(pack==null||!requested()||!environment()){if(pack!=null){var opt=Iris.getCurrentPack().orElseThrow().getShaderPackOptions();pending=BlissPixelOptionGuard.declaredGraph(opt.getOptionSet(),opt.getOptionValues()).orElse("0").equals("1");}FRAME.begin(null,false);return;}
  var current=Iris.getCurrentPack().orElseThrow().getShaderPackOptions();if(!BlissPixelOptionGuard.declaredGraph(current.getOptionSet(),current.getOptionValues()).orElse("0").equals("1")){FRAME.begin(null,false);return;}
  try{sourceQualified=source();var values=options(true);profileQualified=sourceQualified&&BlissPixelContract.options(values);var e=BlissPixelEnvironment.actual();rain=e.rain();clear=e.clear();nearQualified=e.projection();
   if(profileQualified&&e.overworld()){for(Object row:((BlissPixelCompositeView)renderer).shaderlod$passes()){var pass=(BlissPixelPassView)row;if(pass.shaderlod$name().equals(BlissPixelContract.preparation(values)))prep=pass;if(pass.shaderlod$name().equals(BlissPixelContract.reconstruction(values)))taa=pass;}
    layoutQualified=prep!=null&&taa!=null&&Arrays.equals(prep.shaderlod$drawBuffers(),new int[]{0,6})&&Arrays.equals(taa.shaderlod$drawBuffers(),new int[]{5})&&prep.shaderlod$scale().scale()==1&&taa.shaderlod$scale().scale()==1&&t.getCurrentWidth()>=2&&t.getCurrentHeight()>=2;
    for(int i:new int[]{0,1,3,5,6}){var rt=t.get(i);layoutQualified&=rt!=null&&rt.getWidth()==t.getCurrentWidth()&&rt.getHeight()==t.getCurrentHeight()&&rt.getMainTexture()>0&&rt.getAltTexture()>0;}
   }
   key=new BlissPixelFrame.Key(p,pack,t,e.world(),e.camera(),SystemTimeUniforms.COUNTER.getAsInt(),t.getCurrentWidth(),t.getCurrentHeight(),sourceEpoch,OptimizationConfig.generation(),java.util.List.of(OptimizationRuntimeContext.core(),resources()));active=sourceQualified&&profileQualified&&layoutQualified&&nearQualified&&clear;if(!active){pending=true;retryBlocked=true;blockedGeneration=OptimizationConfig.generation();}FRAME.begin(key,active);failure=active?"qualified native frame; waiting for completed history":"source/profile/layout/projection/weather not qualified";
  }catch(RuntimeException|LinkageError unavailable){failure="normal Bliss API unavailable";pending=true;retryBlocked=true;blockedGeneration=OptimizationConfig.generation();FRAME.begin(null,false);}
 }
 private static java.util.List<Integer> resources(){var ids=new java.util.ArrayList<Integer>();for(int i:new int[]{0,1,3,5,6}){var t=targets.get(i);ids.add(t==null?0:t.getMainTexture());ids.add(t==null?0:t.getAltTexture());}return java.util.List.copyOf(ids);}
 public static net.irisshaders.iris.pipeline.WorldRenderingPipeline beforePrepare(net.irisshaders.iris.shaderpack.materialmap.NamespacedId dim){install();if(!pending||recovering)return null;var pack=Iris.getCurrentPack().orElse(null);if(pack==null){pending=false;return null;}var opt=pack.getShaderPackOptions();if(!BlissPixelOptionGuard.declaredGraph(opt.getOptionSet(),opt.getOptionValues()).orElse("0").equals("1")){pending=false;return null;}recovering=true;try{BlissPixelRecovery.nativeReload(Iris.getShaderPackOptionQueue(),Iris::reload);var current=Iris.getCurrentPack().orElseThrow().getShaderPackOptions();if(!BlissPixelOptionGuard.declaredGraph(current.getOptionSet(),current.getOptionValues()).orElse("invalid").equals("0"))throw new IllegalStateException("Bliss native graph0 did not load");pending=false;return Iris.getPipelineManager().preparePipeline(dim);}catch(Exception e){throw new IllegalStateException("Could not restore Bliss native graph before pipeline capture",e);}finally{recovering=false;}}
 public static int uniform(String name){if(name.equals("HistoryReset"))return FRAME.reset()&&((sourceQualified&&profileQualified)||FRAME.wasSelected())?1:0;if(name.equals("ClampReady"))return prepared?1:0;if(name.equals("CurrentEpoch")||name.equals("ProofEpoch"))return FRAME.selected()?FRAME.epoch():0;return FRAME.selected()?1:0;}
 public static double rain(){return rain;}
 private static int output(int attachment){return GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,attachment,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME);}
 private static boolean actualOutput(int attachment,int target){var rt=targets.get(target);int id=output(attachment);return rt!=null&&id>0&&(id==rt.getMainTexture()||id==rt.getAltTexture());}
 private static boolean drawState(){java.nio.ByteBuffer mask=org.lwjgl.BufferUtils.createByteBuffer(4);GL11.glGetBooleanv(GL11.GL_COLOR_WRITEMASK,mask);for(int i=0;i<4;i++)if(mask.get(i)==0)return false;if(GL11.glIsEnabled(GL30.GL_RASTERIZER_DISCARD)||GL11.glGetInteger(GL20.GL_DRAW_BUFFER0)!=GL30.GL_COLOR_ATTACHMENT0)return false;int[] v=new int[4];GL11.glGetIntegerv(GL11.GL_VIEWPORT,v);return Arrays.equals(v,new int[]{0,0,targets.getCurrentWidth(),targets.getCurrentHeight()})&&GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING)>0&&GL30.glCheckFramebufferStatus(GL30.GL_DRAW_FRAMEBUFFER)==GL30.GL_FRAMEBUFFER_COMPLETE&&!GL11.glIsEnabled(GL11.GL_SCISSOR_TEST)&&!GL11.glIsEnabled(GL11.GL_DEPTH_TEST)&&!GL11.glIsEnabled(GL11.GL_STENCIL_TEST)&&!GL11.glIsEnabled(GL11.GL_BLEND);}
 public static void beforeDraw(){startedProgram=0;if(!sourceQualified||!profileQualified||!layoutQualified||taa==null||prep==null)return;int p=GL11.glGetInteger(GL20.GL_CURRENT_PROGRAM);if(p==prep.shaderlod$program().getProgramId()&&drawState()&&actualOutput(GL30.GL_COLOR_ATTACHMENT0,0)&&actualOutput(GL30.GL_COLOR_ATTACHMENT1,6)&&GL11.glGetInteger(GL20.GL_DRAW_BUFFER1)==GL30.GL_COLOR_ATTACHMENT1){startedProgram=p;first=output(GL30.GL_COLOR_ATTACHMENT0);second=output(GL30.GL_COLOR_ATTACHMENT1);}
  if(p==taa.shaderlod$program().getProgramId()){int loc=GL20.glGetUniformLocation(p,"shaderlodBlissPixelClampReady");boolean exact=prepared&&drawState()&&actualOutput(GL30.GL_COLOR_ATTACHMENT0,5)&&BlissPixelGlProof.sample(p,"colortex0",first,targets.getCurrentWidth(),targets.getCurrentHeight())&&BlissPixelGlProof.sample(p,"colortex6",second,targets.getCurrentWidth(),targets.getCurrentHeight());if(loc>=0)GL20.glUniform1i(loc,exact?1:0);boolean outputReady=drawState()&&actualOutput(GL30.GL_COLOR_ATTACHMENT0,5);if(outputReady)startedProgram=p;else requiredTaaOutput(false);}
 }
 public static void afterDraw(){if(startedProgram==0)return;int p=GL11.glGetInteger(GL20.GL_CURRENT_PROGRAM);if(p==startedProgram&&p==prep.shaderlod$program().getProgramId())prepared=drawState()&&first==output(GL30.GL_COLOR_ATTACHMENT0)&&second==output(GL30.GL_COLOR_ATTACHMENT1);if(startedProgram==taa.shaderlod$program().getProgramId())requiredTaaOutput(p==startedProgram&&drawState()&&actualOutput(GL30.GL_COLOR_ATTACHMENT0,5));startedProgram=0;}
 private static void rejectRequiredOutput(){failure="required TAA output/completion unavailable; native graph recovery queued";pending=true;retryBlocked=true;blockedGeneration=OptimizationConfig.generation();}
 private static void requiredTaaOutput(boolean valid){taaReturned=valid;if(!valid)rejectRequiredOutput();}
 private static void completed(boolean proof){if(!proof&&sourceQualified&&profileQualified&&layoutQualified)rejectRequiredOutput();FRAME.returned(key,proof);active=false;}
 public static void end(Object p){if(p!=pipeline)return;completed(sourceQualified&&profileQualified&&layoutQualified&&taaReturned&&pack==Iris.getCurrentPack().orElse(null)&&key!=null&&key.width()==targets.getCurrentWidth()&&key.height()==targets.getCurrentHeight()&&key.source()==sourceEpoch&&key.flags()==OptimizationConfig.generation()&&java.util.Objects.equals(key.core(),java.util.List.of(OptimizationRuntimeContext.core(),resources())));}

 /** Invoked synchronously by the authentic pipeline build; never by a rendering callback. */
 public static void qualifyLoadedSource(net.irisshaders.iris.shaderpack.ShaderPack pack){try{source();}catch(Exception|LinkageError refused){}}
}
